import {AFFINITY_KINDS,affinities,affinityColor,worldReport,placeId} from './world-model.mjs';
export function createWorldPanel({container,toolbar,read,onOpen,onStep,onRun,onExample,onApply,onFocus,onPolicy}){
 const toggle=document.createElement('button');toggle.textContent='World';toggle.id='world-open';toolbar.append(toggle);
 const panel=document.createElement('section');panel.id='world-panel';panel.hidden=true;
 panel.innerHTML='<div class="world-heading"><div><small>CONNECTED WORLD · FIRST RULESET</small><h2>Belonging & movement</h2></div><button id="world-close" aria-label="Close world inspector">×</button></div><p id="world-clock"></p><div class="pills"><button id="world-run">Run world</button><button id="world-step">Advance 30 seconds</button><select id="world-speed" aria-label="World speed"><option value="1">1× speed</option><option value="8" selected>8× speed</option></select></div><div id="world-readout" class="gauges"></div><p id="world-story"></p><button id="world-example">Start Home–Woodland example</button><small>Replaces this board. Undo restores it.</small><label for="world-place">Place</label><select id="world-place"></select><label for="world-object">Inspect object</label><select id="world-object"></select><button id="world-focus">Focus this place</button><p id="world-object-state"></p><label for="world-layer">Affiliation overlay</label><select id="world-layer"></select><div id="world-memberships"></div><button id="world-apply">Save memberships</button><label class="world-policy"><input type="checkbox" id="world-familiar" checked> Prefer familiar suppliers</label><p id="world-feedback" role="status"></p><details><summary>What is simulated?</summary><p>One persistent courier per Home. Each Woodland starts with 12 fuel and bundles 1 per simulation minute, up to 24 in stock. Homes use 1 fuel every 2 minutes and request deliveries below 6. These are authored game units.</p><p>Fuel stays at its source until collection, then travels with its courier. Broken routes cause waiting. Stored places and cargo remain accounted for. No starvation mechanic.</p><p>Shared memberships modestly influence supplier choice alongside distance. They do not imply hostility. The overlay marks affiliations; architectural styles are still to come.</p><p>Town households and the older village demo remain separate simulations. Other local walkers are illustrative. Fantastical capabilities can be added to the same entity model; magic is not yet simulated. World time pauses when this tab is hidden or closed.</p></details>';
 container.insertBefore(panel,container.querySelector('.drawer-head').nextSibling);
 const style=document.createElement('style');style.textContent='#world-panel{padding:18px;border-bottom:1px solid #bac6b2;background:#f4f3e7;display:grid;gap:9px}#world-panel[hidden]{display:none}#world-panel h2{font-size:21px;margin:3px 0}#world-panel p{margin:2px 0;line-height:1.5;font-size:12px}#world-panel small{font-size:10px;color:#61715a}#world-panel select,#world-panel input[type=text]{width:100%;min-width:0;padding:8px;border:1px solid #c6cbb9;border-radius:6px;background:white;color:#263d30}#world-panel label{font-size:12px}.world-heading{display:flex;justify-content:space-between;align-items:center}.world-membership{border-top:1px solid #d7ddcb;padding:7px 0;display:grid;gap:4px}.world-inherit{display:flex;align-items:center;gap:6px}.world-inherit input,#world-familiar{width:auto!important}.world-policy{display:flex;align-items:center;gap:7px}#world-story{background:#e5ebdf;border-radius:6px;padding:8px!important}#world-panel .gauges{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}#world-panel .gauge{display:grid;padding:7px;background:#fff9;border-radius:6px}#world-panel .gauge strong{font-size:18px}#world-panel .gauge span{font-size:10px}#sandbox-tools{flex-wrap:wrap;max-width:calc(100vw - 24px)}';document.head.append(style);
 const $=id=>panel.querySelector('#'+id);let place='',object='',editKey='',overlayKind='tribal',listKey='',selectedInstance=null;
 for(const kind of AFFINITY_KINDS){const opt=document.createElement('option');opt.value=kind;opt.textContent=kind[0].toUpperCase()+kind.slice(1);$('world-layer').append(opt);const row=document.createElement('div');row.className='world-membership';const label=document.createElement('label');label.htmlFor='world-'+kind;label.textContent=opt.textContent;const input=document.createElement('input');input.type='text';input.id='world-'+kind;input.placeholder='Names, separated by commas';input.maxLength=720;const inherit=document.createElement('label');inherit.className='world-inherit';const check=document.createElement('input');check.type='checkbox';check.id='world-inherit-'+kind;check.onchange=()=>input.disabled=check.checked;inherit.append(check,document.createTextNode('Inherit from containing object'));row.append(label,input,inherit);$('world-memberships').append(row);}
 $('world-layer').value=overlayKind;
 function open(){panel.hidden=false;onOpen();refresh();container.scrollTop=0;}
 toggle.onclick=open;$('world-close').onclick=()=>panel.hidden=true;
 $('world-run').onclick=()=>onRun();$('world-step').onclick=()=>onStep(30);$('world-example').onclick=()=>onExample();$('world-speed').onchange=()=>{};
 $('world-place').onchange=()=>{place=$('world-place').value;object=place;listKey='';editKey='';refresh();};$('world-object').onchange=()=>{object=$('world-object').value;editKey='';refresh();};$('world-focus').onclick=()=>onFocus(read().world.entities[place]?.instanceId);
 $('world-layer').onchange=()=>overlayKind=$('world-layer').value;
 $('world-familiar').onchange=()=>onPolicy($('world-familiar').checked);
 $('world-apply').onclick=async()=>{try{const changes=AFFINITY_KINDS.map(kind=>({kind,inherit:$('world-inherit-'+kind).checked,names:$('world-'+kind).value.split(',').map(n=>n.trim()).filter(Boolean)}));await onApply(object,changes);editKey='';$('world-feedback').textContent='Memberships saved. Undo is available.';refresh();}catch(e){$('world-feedback').textContent=e.message;}};
 function refresh(){const {world,running,busy,selected}=read();if(!world)return;const report=worldReport(world);$('world-clock').textContent='World time '+Math.floor(report.seconds/60)+'m '+report.seconds%60+'s · '+(running?'Running':'Paused');$('world-run').textContent=running?'Pause world':'Run world';$('world-readout').replaceChildren(...[['Couriers',report.people],['Delivered fuel',report.delivered],['Fuel in transit',report.cargo],['Stored fuel',report.stock],['Waiting',report.waiting],['Objects',report.objects]].map(([label,value])=>{const el=document.createElement('div');el.className='gauge';const n=document.createElement('strong');n.textContent=value;const l=document.createElement('span');l.textContent=label;el.append(n,l);return el;}));
  const agents=Object.values(world.agents).filter(a=>world.entities[a.id]?.active);$('world-story').textContent=agents.map(a=>a.trip?(a.cargo?'Carrying '+a.cargo+' fuel to ':'Walking to ')+world.entities[a.trip.target]?.name:a.phase==='waiting'?'Waiting for a connected route or available fuel':a.phase==='idle'?'Home has enough fuel':'Courier is stored').join(' · ')||'Place a Home and Woodland, or start the connected example.';
  const places=Object.values(world.entities).filter(e=>e.active&&e.kind==='place');if(selected&&selected!==selectedInstance&&world.entities[placeId(selected)]?.active){place=placeId(selected);object=place;listKey='';editKey='';}selectedInstance=selected;
  if(!places.some(e=>e.id===place)){place=places[0]?.id||'';object=place;}
  const options=Object.values(world.entities).filter(e=>e.active&&(e.id===place||e.instanceId&&e.instanceId===world.entities[place]?.instanceId));
  const key=JSON.stringify([places.map(e=>[e.id,e.name]),options.map(e=>[e.id,e.name]),place]);if(key!==listKey){listKey=key;const option=e=>{const o=document.createElement('option');o.value=e.id;o.textContent=(e.kind==='place'?'':e.kind+' · ')+e.name;return o;};$('world-place').replaceChildren(...places.map(option));$('world-place').value=place;$('world-object').replaceChildren(...options.map(option));if(!options.some(e=>e.id===object))object=place;$('world-object').value=object;}
  const entity=world.entities[object],inventory=world.inventories[object],agent=world.agents[object];$('world-object-state').textContent=agent?agent.phase+' · '+agent.cargo+' fuel carried · '+Math.floor(agent.metres)+' metres travelled':inventory?inventory.fuel+' fuel here · '+(entity?.capabilities.join(', ')||'World production not implemented for this place'):entity?'Persistent '+entity.kind+' · memberships may override the containing object':'Choose a placed object';
  const nextEdit=JSON.stringify([object,entity?.affinities,...AFFINITY_KINDS.map(k=>affinities(world,object,k))]);if(nextEdit!==editKey){editKey=nextEdit;for(const kind of AFFINITY_KINDS){const inherited=!Object.hasOwn(entity?.affinities||{},kind);$('world-inherit-'+kind).checked=inherited;$('world-'+kind).disabled=inherited;$('world-'+kind).value=entity?affinities(world,object,kind).map(t=>world.groups[t.groupId]?.name).filter(Boolean).join(', '):'';}}
  for(const name of ['world-step','world-example','world-apply','world-focus'])$(name).disabled=busy||name!=='world-example'&&!places.length;$('world-familiar').checked=world.policy.preferFamiliar;
 }
 return {refresh,open,view:()=>({kind:overlayKind,selectedId:object}),speed:()=>Number($('world-speed').value),feedback:message=>$('world-feedback').textContent=message};
}
